import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  // spec: specs/hal-engine-tool-input-validation#1
  it('returns a required-property rejection without invoking the executor', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'sunny');

    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      executor
    );

    const response = await registry.execute('get_weather', {});

    const {calls} = executor.mock;
    expect({executorCalled: calls.length, result: response.result}).toEqual({
      executorCalled: 0,
      result: 'Input validation failed at /location: property is required',
    });
  });

  it('names the nested required property in a schema rejection', async () => {
    const registry = new ToolRegistry();

    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {
            address: {
              type: 'object',
              properties: {city: {type: 'string'}},
              required: ['city'],
            },
          },
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('get_weather', {address: {}});

    expect(response.result).toMatch(/\/address\/city.*required|required.*\/address\/city/i);
  });

  it('names the top-level property and expected type for a type rejection', async () => {
    const registry = new ToolRegistry();

    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('get_weather', {location: 42});

    expect(response.result).toMatch(/\/location.*string|string.*\/location/i);
  });

  it('names the nested property path for a type rejection', async () => {
    const registry = new ToolRegistry();

    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for an address',
        inputSchema: {
          type: 'object',
          properties: {
            address: {
              type: 'object',
              properties: {city: {type: 'string'}},
            },
          },
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('get_weather', {address: {city: 42}});

    expect(response.result).toMatch(/\/address\/city.*string|string.*\/address\/city/i);
  });

  it('names the property path when an enum constraint rejects input', async () => {
    const registry = new ToolRegistry();

    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}},
          required: ['unit'],
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('get_weather', {unit: 'kelvin'});

    expect(response.result).toMatch(/\/unit.*enum|enum.*\/unit/i);
  });

  // spec: specs/hal-engine-tool-input-validation#5
  it('passes valid input and undeclared properties through unchanged once', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Paris', timezone: 'Europe/Paris'};
    const executorInputs: Array<Record<string, unknown>> = [];

    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async receivedInput => {
        executorInputs.push(receivedInput);
        return 'sunny';
      }
    );

    await registry.execute('get_weather', input);

    expect(executorInputs).toEqual([input]);
  });

  // spec: specs/hal-engine-tool-input-validation#9
  it('reuses a static validator after the schema object changes', async () => {
    const registry = new ToolRegistry();
    const definition = {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    };
    const executor = jest.fn(async () => 'sunny');

    registry.register(definition, executor);
    definition.inputSchema = {
      type: 'object',
      properties: {location: {type: 'number'}},
      required: ['location'],
    };

    await registry.execute('get_weather', {location: 'Paris'});

    expect(executor).toHaveBeenCalledTimes(1);
  });

  // spec: specs/hal-engine-tool-input-validation#10
  it('validates a function-valued definition against its current schema', async () => {
    const registry = new ToolRegistry();
    let definitionCalls = 0;
    const executorInputs: Array<Record<string, unknown>> = [];

    registry.register(
      () => {
        definitionCalls += 1;
        const type = definitionCalls % 2 === 0 ? 'number' : 'string';
        return {
          name: 'get_weather',
          description: 'Get weather for a location',
          inputSchema: {type: 'object', properties: {location: {type}}, required: ['location']},
        };
      },
      async input => {
        executorInputs.push(input);
        return 'sunny';
      }
    );

    const firstResponse = await registry.execute('get_weather', {location: 42});
    const secondResponse = await registry.execute('get_weather', {location: 'Paris'});

    expect({
      firstResponse: firstResponse.result,
      secondResponse: secondResponse.result,
      executorInputs,
    }).toEqual({
      firstResponse: 'sunny',
      secondResponse: 'sunny',
      executorInputs: [{location: 42}, {location: 'Paris'}],
    });
  });
});
  it('runs another round after a tool call and streams both rounds in order', async () => {
    const provider = scriptedProvider([
      [TOOL_CALL, STOP_FOR_TOOL],
      [{type: 'text', text: 'the answer'}, STOP_DONE],
    ]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'found it'}));

    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));

    expect(chunks.map(c => c.type)).toEqual(['tool_use', 'stop', 'text', 'stop']);
  });

  it('stops after one round when nothing asked for a tool', async () => {
    const provider = scriptedProvider([[{type: 'text', text: 'done'}, STOP_DONE], [{type: 'text', text: 'never'}]]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'x'}));

    const text = await orchestrator.processMessage(createSession('ask'));

    expect(text).toBe('done');
  });

  it('stops asking for tools once maxToolRounds is spent', async () => {
    const alwaysTools = Array.from({length: 10}, () => [TOOL_CALL, STOP_FOR_TOOL]);
    const orchestrator = createChatOrchestrator(
      scriptedProvider(alwaysTools),
      promptBuilder,
      registryReturning({result: 'again'}),
      {maxToolRounds: 2}
    );

    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));

    expect(chunks.filter(c => c.type === 'tool_use')).toHaveLength(3);
  });

  it('forwards the client messages a tool returned as one tool_result chunk', async () => {
    const forwarded: OutgoingMessage = {type: 'entry_commit', index: 7};
    const orchestrator = createChatOrchestrator(
      scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]),
      promptBuilder,
      registryReturning({result: 'r', clientMessages: [forwarded]})
    );

    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));

    expect(chunks).toContainEqual({type: 'tool_result', clientMessages: [forwarded]});
  });

  it('appends an upserted entry to the session and rewrites its index to match', async () => {
    const entry: SessionEntry = {role: 'assistant', content: 'from the tool', timestamp: SENT_AT, isStreaming: false};
    const orchestrator = createChatOrchestrator(
      scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]),
      promptBuilder,
      registryReturning({result: 'r', clientMessages: [{type: 'entry_upsert', index: 999, entry}]})
    );
    const session = createSession('ask');

    const chunks = await chunksFrom(orchestrator.processMessageStream(session));

    expect(chunks).toContainEqual({
      type: 'tool_result',
      clientMessages: [{type: 'entry_upsert', index: session.entries.length - 1, entry}],
    });
  });

  it('asks for suppression when the tool says the reply is already handled', async () => {
    const orchestrator = createChatOrchestrator(
      scriptedProvider([[TOOL_CALL, STOP_FOR_TOOL], [STOP_DONE]]),
      promptBuilder,
      registryReturning({result: 'r', suppressAssistantResponse: true})
    );

    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));

    expect(chunks.map(c => c.type)).toEqual(['tool_use', 'stop', 'suppress_output', 'stop']);
  });

  it('joins the text of every round, not only the last', async () => {
    let seen = '';
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, responseText) => {
        seen = responseText;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [{type: 'text', text: 'first '}, TOOL_CALL, STOP_FOR_TOOL],
        [{type: 'text', text: 'second'}, STOP_DONE],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seen).toBe('first second');
  });

  it('keeps the usage an earlier round reported when a later round reports none', async () => {
    const usage: UsageMetadata = {inputTokens: 11, outputTokens: 3, totalTokens: 14};
    let seen: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, reported) => {
        seen = reported;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage}],
        [{type: 'text', text: 'done'}, STOP_DONE],
      ]),
      promptBuilder,
      registryReturning({result: 'r'}),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(seen).toEqual(usage);
  });
});
