import Ajv, {type ErrorObject, type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
  validators?: WeakMap<object, ValidateFunction>;
}

const ajv = new Ajv({
  strict: false,
  validateFormats: false,
  coerceTypes: false,
  useDefaults: false,
} as ConstructorParameters<typeof Ajv>[0]);

function validationMessage(errors: ErrorObject[]): string {
  const error = errors[0];
  if (!error) return 'Input failed schema validation';

  const details = error as ErrorObject & {instancePath?: string; dataPath?: string};
  const params = details.params as Record<string, unknown>;
  const missingProperty = params.missingProperty;
  const schemaPath = details.schemaPath.replace(/^#/, '');
  const propertiesPath = schemaPath.replace(/\/properties\/([^/]+)/g, '/$1');
  const propertyPathFromSchema = propertiesPath.replace(/\/(?:required|type|enum)$/, '') || '/';
  const instancePath = details.instancePath ?? details.dataPath;
  const path = instancePath ? normalizeInstancePath(instancePath) : propertyPathFromSchema;
  const hasMissingProperty = details.keyword === 'required' && typeof missingProperty === 'string';
  const propertyPath = hasMissingProperty
    ? path === '/'
      ? `/${missingProperty}`
      : `${path}/${missingProperty}`
    : path;
  if (details.keyword === 'required') return `Input validation failed at ${propertyPath}: property is required`;
  if (details.keyword === 'type') return `Input validation failed at ${path}: must be ${String(params.type)}`;
  if (details.keyword === 'enum') return `Input validation failed at ${path}: value must match the enum constraint`;
  return `Input validation failed at ${path}: ${details.message ?? 'schema constraint failed'}`;
}

function normalizeInstancePath(path: string): string {
  if (path.startsWith('/')) return path;
  if (!path.startsWith('.')) return path || '/';
  const segments = path.slice(1).split('.');
  const escapedSegments = segments.map(escapeJsonPointerSegment);
  const pointerSegments = escapedSegments.map(segment => `/${segment}`);
  return pointerSegments.join('') || '/';
}

function escapeJsonPointerSegment(segment: string): string {
  const withoutTilde = segment.replace(/~/g, '~0');
  return withoutTilde.replace(/\//g, '~1');
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validator = typeof definition === 'function' ? undefined : this.compile(resolved);
    this.tools.set(resolved.name, {
      definitionSource: definition,
      execute,
      validator,
      validators: typeof definition === 'function' ? new WeakMap<object, ValidateFunction>() : undefined,
    });
  }

  private compile(definition: ToolDefinition): ValidateFunction {
    try {
      return ajv.compile(definition.inputSchema);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid input schema for tool ${definition.name}: ${message}`, {cause: error});
    }
  }

  private validatorFor(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
    if (tool.validator) return tool.validator;

    const cached = tool.validators?.get(definition.inputSchema);
    if (cached) return cached;

    const validator = this.compile(definition);
    tool.validators?.set(definition.inputSchema, validator);
    return validator;
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates tool input and returns rejections; only an unknown tool name throws (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = this.validatorFor(tool, definition);
    if (!validator(input)) {
      const result = validationMessage(validator.errors ?? []);
      log.warn('tool', 'input rejected', {name, result});
      return {result};
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | Implemented          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: returns a required-property rejection without invoking the executor](../../src/orchestration/tools/registry.test.ts#L6), [validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- A nested missing property is reported with its complete JSON Pointer path, including the containing object ([validated by: names the nested required property in a schema rejection](../../src/orchestration/tools/registry.test.ts#L31)).
- A nested wrong-typed property is reported with its complete JSON Pointer path and expected type ([validated by: names the nested property path for a type rejection](../../src/orchestration/tools/registry.test.ts#L78)).
- An enum rejection is reported with the failing property's JSON Pointer path ([validated by: names the property path when an enum constraint rejects input](../../src/orchestration/tools/registry.test.ts#L103)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: names the top-level property and expected type for a type rejection](../../src/orchestration/tools/registry.test.ts#L57), [validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input and undeclared properties through unchanged once](../../src/orchestration/tools/registry.test.ts#L125)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: reuses a static validator after the schema object changes](../../src/orchestration/tools/registry.test.ts#L152)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: validates a function-valued definition against its current schema](../../src/orchestration/tools/registry.test.ts#L179)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
- A rejected tool call is visible to the provider as a `tool_result`, and a corrected retry can execute and complete the message without rejecting `processMessage` ([validated by: feeds a schema rejection back for a corrected retry](../../src/orchestration/chatOrchestrator.test.ts#L403)).
};

const registryReturning = (response: ToolResponse): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}},
    async () => response
  );
  return registry;
};

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};
const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
const STOP_DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

const chunksFrom = async (stream: AsyncGenerator<MessageChunk>): Promise<MessageChunk[]> => {
  const chunks: MessageChunk[] = [];
  for await (const chunk of stream) chunks.push(chunk);
  return chunks;
};

describe('ChatOrchestrator tool loop', () => {
  // spec: specs/hal-engine-tool-input-validation#8
  it('feeds a schema rejection back for a corrected retry', async () => {
    const requests: SendMessageParams[] = [];
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        requests.push(params);
        if (requests.length === 1) {
          yield {type: 'tool_use', toolCall: {id: 'invalid', name: 'lookup', input: {}}};
          yield STOP_FOR_TOOL;
          return;
        }
        if (requests.length === 2) {
          yield {type: 'tool_use', toolCall: {id: 'corrected', name: 'lookup', input: {location: 'Paris'}}};
          yield STOP_FOR_TOOL;
          return;
        }
        yield {type: 'text', text: 'forecast complete'};
        yield STOP_DONE;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const executor = jest.fn(async () => 'sunny');
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup',
        description: 'looks things up',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      executor
    );

    const result = await createChatOrchestrator(provider, promptBuilder, registry).processMessage(createSession('ask'));
    const secondRequest = requests[1];
    const toolResultMessage = secondRequest?.messages.find(
      (message): message is ToolResultMessage => message.role === 'user' && typeof message.content !== 'string'
    );
    const toolResult = toolResultMessage?.content.find(content => content.type === 'tool_result');
    const rejection = toolResult?.content;
    const {calls} = executor.mock;

    expect({
      result,
      rejection,
      executorCalls: calls.length,
    }).toEqual({
      result: 'forecast complete',
      rejection: 'Input validation failed at /location: property is required',
      executorCalls: 1,
    });
  });

  it('runs another round after a tool call and streams both rounds in order', async () => {
    const provider = scriptedProvider([
      [TOOL_CALL, STOP_FOR_TOOL],
      [{type: 'text', text: 'the answer'}, STOP_DONE],
    ]);
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registryReturning({result: 'found it'}));

    const chunks = await chunksFrom(orchestrator.processMessageStream(createSession('ask')));

    expect(chunks.map(c => c.type)).toEqual(['tool_use', 'stop', 'text', 'stop']);
  });
